14	/**
15	 * First step of {@code POST /api/owners}. Rejects a body that is missing (absent) or blank
16	 * (whitespace only) in any of firstName, lastName, address, city or telephone — {@code @Size(min = 1)}
17	 * on the DTO does not catch a whitespace-only value, so the check is explicit here. The remaining
18	 * schema constraints (pattern, max length) are validated too, so a bad value is still a 400.
19	 *
20	 * <p>Binds the body directly (no {@code @Valid}) so that a missing field surfaces as this rule's
21	 * {@code errors} response rather than the generic schema-validation escalation, and publishes the
22	 * body for {@link BuildOwner} to consume.
23	 */
24	public class ValidateOwnerFields {
25	
26	    public void service(@RequestBody OwnerFieldsDto request, Validator validator, Out<OwnerFieldsDto> validated)
27	            throws MissingOwnerFieldsException {
28	        List<String> errors = new ArrayList<>();
29	        normalizeAddress(request);
30	        addIfBlank(errors, "firstName", request.getFirstName());
31	        addIfBlank(errors, "lastName", request.getLastName());
32	        addIfBlank(errors, "address", request.getAddress());
33	        addIfBlank(errors, "city", request.getCity());
34	        normalizeTelephone(errors, request);
35	        for (ConstraintViolation<OwnerFieldsDto> violation : validator.validate(request)) {
36	            String field = violation.getPropertyPath().toString();
37	            if (!field.isEmpty() && !errors.contains(field)) {
38	                errors.add(field);
39	            }
40	        }
41	        validatePostcode(errors, request);
42	        if (!errors.isEmpty()) {
43	            throw new MissingOwnerFieldsException(errors);
44	        }
45	        normalizeEmail(request);
46	        validated.set(request);
47	    }
48	
49	    /**
50	     * Email is optional. When absent nothing is done; when present the schema {@code @Email}
51	     * constraint (checked above) has already rejected a syntactically invalid address with a
52	     * {@code 400}, so a value reaching here is valid and is stored and returned lower-cased.
53	     */
54	    private static void normalizeEmail(OwnerFieldsDto request) {
55	        String email = request.getEmail();
56	        if (email != null) {
57	            request.setEmail(email.toLowerCase(java.util.Locale.ROOT));
58	        }
59	    }
60	
61	    /**
62	     * Canonically normalize the address (trim, collapse whitespace, upper-case, expand common
63	     * abbreviations) and write it back onto the request so it is stored and returned in normalized
64	     * form. Running before the blank check means an address that is whitespace-only — and so blank
65	     * after normalization — is rejected as an {@code address} required-field error (400).
66	     */
67	    private static void normalizeAddress(OwnerFieldsDto request) {
68	        request.setAddress(AddressNormalizer.normalize(request.getAddress()));
69	    }
70	
71	    /**
72	     * Postcode is optional and validated only when present. Its 4-digit format is enforced by the
73	     * schema {@code @Pattern} (checked above, so a malformed value is already a {@code postcode}
74	     * error). When it is well-formed it must also be in range for the region derived from the
75	     * owner's city (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); a city with no known region
76	     * accepts any 4-digit postcode. An out-of-range postcode is a {@code postcode} error (400).
77	     */
78	    private static void validatePostcode(List<String> errors, OwnerFieldsDto request) {
79	        String postcode = request.getPostcode();
80	        if (postcode != null && !errors.contains("postcode")
81	                && !Postcodes.isValidForCity(postcode, request.getCity())) {
82	            errors.add("postcode");
83	        }
84	    }
85	
86	    private static void addIfBlank(List<String> errors, String name, String value) {
87	        if (value == null || value.isBlank()) {
88	            errors.add(name);
89	        }
90	    }
91	
92	    /**
93	     * Normalize the telephone into E.164 form. Spaces, dashes and brackets are stripped. A leading
94	     * '+' with country code is kept as-is; otherwise the number is assumed to be Australian ('+61')
95	     * and a single leading '0' is dropped from the national digits. The result must have 8 to 15
96	     * digits after the '+'. The E.164 value is written back onto the request so it is stored and
97	     * returned as {@code telephone}. Anything that cannot form a valid E.164 number is a
98	     * {@code telephone} error (400).
99	     */
100	    private static void normalizeTelephone(List<String> errors, OwnerFieldsDto request) {
101	        String e164 = toE164(request.getTelephone());
102	        if (e164 == null) {
103	            errors.add("telephone");
104	            return;
105	        }
106	        request.setTelephone(e164);
107	    }
108	
109	    /**
110	     * Country codes with a fixed national-number length. When a number's country code appears here
111	     * its national digits (everything after the code) must match exactly, otherwise it is rejected;
112	     * country codes not listed fall back to the generic 8–15 total-digit rule. '+61' (Australia)
113	     * requires 9 national digits, '+1' (NANP) requires 10.
114	     */
115	    private static final java.util.Map<String, Integer> NATIONAL_LENGTH_BY_COUNTRY =
116	            java.util.Map.of("61", 9, "1", 10);
117	
118	    /**
119	     * Convert a raw telephone into E.164 form, or return {@code null} when it cannot form a valid
120	     * E.164 number (fewer than 8 or more than 15 digits after the '+', a national-number length that
121	     * is wrong for its country code, or stray non-digit characters remaining after the allowed
122	     * separators are stripped).
123	     */
124	    static String toE164(String value) {
125	        if (value == null) {
126	            return null;
127	        }
128	        String cleaned = value.replaceAll("[\\s()-]", "");
129	        String digits;
130	        if (cleaned.startsWith("+")) {
131	            digits = cleaned.substring(1);
132	        }
133	        else {
134	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
135	            digits = "61" + national;
136	        }
137	        if (!digits.matches("[0-9]{8,15}")) {
138	            return null;
139	        }
140	        if (!hasValidNationalLength(digits)) {
141	            return null;
142	        }
143	        return "+" + digits;
144	    }
145	
146	    /**
147	     * For a country code with a fixed national-number length, check the national digits (everything
148	     * after the code) match that length exactly. Unknown country codes pass (already bounded by the
149	     * generic 8–15 total-digit rule).
150	     */
151	    private static boolean hasValidNationalLength(String digits) {
152	        for (java.util.Map.Entry<String, Integer> entry : NATIONAL_LENGTH_BY_COUNTRY.entrySet()) {
153	            String code = entry.getKey();
154	            if (digits.startsWith(code)) {
155	                return digits.length() - code.length() == entry.getValue();
156	            }
157	        }
158	        return true;
159	    }
160	}
